<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Solmar Bay — Open World Crime Game</title>
<style>
  html,body{margin:0;padding:0;background:#0b1020;height:100%;overflow:hidden;font-family:'Segoe UI',Arial,sans-serif}
  #wrap{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(1200px 700px at 50% 30%,#16224a,#0b1020)}
  canvas{display:block;background:#1c2b1f;box-shadow:0 0 60px rgba(0,0,0,.7);border:2px solid #2a3a5f;border-radius:6px}
  #hint{position:fixed;left:12px;bottom:10px;color:#9fb4d8;font-size:12px;opacity:.8;pointer-events:none}
</style>
</head>
<body>
<div id="wrap"><canvas id="game" width="1280" height="800"></canvas></div>
<script>
"use strict";
/* ============================================================
   SOLMAR BAY — an original top-down 2D open-world crime game.
   Own city, own characters, own story. No Rockstar IP.
   Canvas 2D + inline WebAudio. Zero dependencies, zero network.
   ============================================================ */
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const W = 1280, H = 800;
const WORLD = { w: 3400, h: 2600 };
const ROAD = 96;            // road width
const BLOCK = 420;          // block pitch (road centre to road centre)
const clamp = (v,a,b)=>v<a?a:v>b?b:v;
const rand = (a,b)=>a+Math.random()*(b-a);
const irand = (a,b)=>Math.floor(rand(a,b+1));
const dist = (ax,ay,bx,by)=>Math.hypot(ax-bx,ay-by);
const TAU = Math.PI*2;
function angLerp(a,b,t){ let d=(b-a)%TAU; if(d>Math.PI)d-=TAU; if(d<-Math.PI)d+=TAU; return a+d*t; }

// ---------- districts ----------
const DISTRICTS = [
  {name:'Harbor',        x:0,    y:0,    w:1100, h:800,  col:'#3d6b8e', label:'#bfe3ff'},
  {name:'Old Town',      x:1100, y:0,    w:1150, h:800,  col:'#7a6a4f', label:'#ffe9b0'},
  {name:'Market District',x:2250,y:0,    w:1150, h:800,  col:'#6b4f7a', label:'#f3d1ff'},
  {name:'Casino Strip',  x:0,    y:800,  w:1100, h:850,  col:'#8e3d5c', label:'#ffd3e2'},
  {name:'Downtown',      x:1100, y:800,  w:1150, h:850,  col:'#4f6b7a', label:'#cfeaff'},
  {name:'Airport',       x:2250, y:800,  w:1150, h:850,  col:'#5c6b3d', label:'#e8ffc9'},
  {name:'Stadium',       x:0,    y:1650, w:1700, h:950,  col:'#3d7a52', label:'#d2ffd9'},
  {name:'Hills',         x:1700, y:1650, w:1700, h:950,  col:'#6b5a3d', label:'#ffe4b3'},
  {name:'Pier',          x:1700, y:800,  w:550,  h:850,  col:'#2f5f7a', label:'#bfe9ff'},
];
function districtAt(x,y){ for(const d of DISTRICTS) if(x>=d.x&&x<d.x+d.w&&y>=d.y&&y<d.y+d.h) return d; return DISTRICTS[4]; }

// ---------- city layout: roads on a grid, buildings inside blocks ----------
const ROADS_X = [], ROADS_Y = [];
for(let x=210;x<WORLD.w;x+=BLOCK) ROADS_X.push(x);
for(let y=210;y<WORLD.h;y+=BLOCK) ROADS_Y.push(y);
function onRoad(x,y){
  for(const rx of ROADS_X) if(Math.abs(x-rx)<ROAD/2+6) return true;
  for(const ry of ROADS_Y) if(Math.abs(y-ry)<ROAD/2+6) return true;
  return false;
}
const BUILDINGS = [];
(function buildCity(){
  const palette=['#5a6b8c','#7c6a55','#6a7a5c','#8c5a6b','#4f5f7a','#7a7a4f','#5c4f7a','#6b4f4f'];
  for(let bx=0; bx<8; bx++) for(let by=0; by<6; by++){
    const x0=bx*BLOCK+ROAD/2+14, y0=by*BLOCK+ROAD/2+14;
    const bw=BLOCK-ROAD-28, bh=BLOCK-ROAD-28;
    const n=irand(2,3);
    for(let i=0;i<n;i++){
      const w=rand(70,150), h=rand(60,130);
      const x=x0+rand(0,Math.max(1,bw-w)), y=y0+rand(0,Math.max(1,bh-h));
      BUILDINGS.push({x,y,w,h,col:palette[(bx*7+by*3+i)%palette.length],hgt:irand(1,4)});
    }
  }
  // landmark: casino tower on the Strip, stadium bowl, airport terminal
  BUILDINGS.push({x:300,y:1050,w:260,h:170,col:'#a03d6b',hgt:6,land:'CASINO ROYALE'});
  BUILDINGS.push({x:300,y:1850,w:420,h:260,col:'#3d7a52',hgt:2,land:'SOLMAR STADIUM'});
  BUILDINGS.push({x:2600,y:1100,w:380,h:160,col:'#5c6b3d',hgt:3,land:'SOLMAR AIRPORT'});
})();
function hitBuilding(x,y,r){
  for(const b of BUILDINGS) if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h) return b;
  return null;
}
function solidAt(x,y,r){ return x<r||y<r||x>WORLD.w-r||y>WORLD.h-r||!!hitBuilding(x,y,r); }

// ---------- game state ----------
const SAVE_KEY='solmar-bay-save-v1';
const G = {
  mode:'title',            // title | play | pause | dead | win
  time:0, cash:120, health:100, wanted:0, wantedHeat:0,
  score:0, kills:0, carsStolen:0,
  player:{x:1500,y:1150,a:-Math.PI/2,speed:0,inCar:null,walk:0,gun:1},
  cam:{x:1500,y:1150},
  keys:{}, mouse:{x:640,y:400,down:false},
  cars:[], peds:[], cops:[], bullets:[], pickups:[], parts:[],
  mission:0, missionStep:0, missionText:'', objective:null, missionTimer:0,
  msg:'', msgT:0, shake:0, muted:false, saveFlash:0,
  story:[
    'Marco Vane: "Kid, Solmar Bay eats the slow. Prove yourself and the city is yours."',
    'Marco Vane: "The Harbor crew needs a driver. No questions, no cops. You in?"',
    'Marco Vane: "One last job — the Casino Royale vault. Then we\'re legends."',
  ],
};
const MISSIONS = [
  {name:'M1 · The Pickup', brief:'Drive to the Harbor dock and pick up Marco\'s package.', target:{x:420,y:420}, kind:'goto',
   done:'Package secured. Marco is impressed.'},
  {name:'M2 · Market Run', brief:'Collect 3 supply crates across the Market District.', target:null, kind:'collect', need:3,
   done:'Crates delivered. The crew trusts you now.'},
  {name:'M3 · The Getaway', brief:'Lose the cops — drop your wanted level to 0, then reach the Stadium.', target:{x:500,y:1980}, kind:'escape',
   done:'Clean getaway. You drive like a ghost.'},
  {name:'M4 · Casino Royale', brief:'Storm the Casino Royale and take down 4 guards. Watch the wanted level!', target:{x:430,y:1135}, kind:'fight', need:4,
   done:'Vault cracked. SOLMAR BAY IS YOURS.'},
];
function setMission(i){
  G.mission=i; G.missionStep=0;
  const m=MISSIONS[i];
  G.missionText=m.name+' — '+m.brief;
  G.objective = m.target?{x:m.target.x,y:m.target.y}:null;
  G.missionTimer=0;
  flash(m.name);
  if(G.story[i]) flash(G.story[i]);
}
function flash(t){ G.msg=t; G.msgT=6; }
function addCash(n){ G.cash+=n; G.score+=n; }
</script>

<script>
"use strict";
/* ---------- audio: created ONLY on a user gesture ---------- */
let AC=null, engineOsc=null, engineGain=null;
function ensureAudio(){
  if(AC) return;
  try{
    AC = new (window.AudioContext||window.webkitAudioContext)();
    engineOsc = AC.createOscillator(); engineOsc.type='sawtooth'; engineOsc.frequency.value=55;
    engineGain = AC.createGain(); engineGain.gain.value=0;
    const lp = AC.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=420;
    engineOsc.connect(lp); lp.connect(engineGain); engineGain.connect(AC.destination);
    engineOsc.start();
  }catch(e){ AC=null; }
}
function beep(freq,dur,type,vol){
  if(!AC||G.muted) return;
  try{
    const o=AC.createOscillator(), g=AC.createGain();
    o.type=type||'square'; o.frequency.value=freq;
    g.gain.setValueAtTime(vol||0.08,AC.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001,AC.currentTime+dur);
    o.connect(g); g.connect(AC.destination); o.start(); o.stop(AC.currentTime+dur);
  }catch(e){}
}
function noiseBurst(dur,vol){
  if(!AC||G.muted) return;
  try{
    const n=AC.createBufferSource(), buf=AC.createBuffer(1,AC.sampleRate*dur,AC.sampleRate), d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*(1-i/d.length);
    n.buffer=buf; const g=AC.createGain(); g.gain.value=vol||0.15;
    n.connect(g); g.connect(AC.destination); n.start();
  }catch(e){}
}
const sfx = {
  shoot(){ noiseBurst(0.09,0.18); beep(180,0.08,'square',0.06); },
  pickup(){ beep(660,0.09,'sine',0.1); setTimeout(()=>beep(990,0.12,'sine',0.1),80); },
  steal(){ beep(220,0.15,'sawtooth',0.08); },
  siren(){ beep(740,0.18,'sine',0.05); setTimeout(()=>beep(560,0.18,'sine',0.05),190); },
  crash(){ noiseBurst(0.2,0.2); },
  mission(){ [523,659,784].forEach((f,i)=>setTimeout(()=>beep(f,0.16,'triangle',0.1),i*110)); },
  hurt(){ beep(140,0.2,'sawtooth',0.12); },
};

/* ---------- input ---------- */
const KEYMAP={KeyW:'up',ArrowUp:'up',KeyS:'down',ArrowDown:'down',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',ShiftLeft:'run',ShiftRight:'run',KeyE:'use',Space:'brake',KeyP:'pause',KeyL:'save',KeyM:'mute'};
addEventListener('keydown',e=>{
  ensureAudio();
  if(e.code==='Space') e.preventDefault();
  const k=KEYMAP[e.code]; if(k) G.keys[k]=true;
  if(e.code==='KeyP'&&(G.mode==='play'||G.mode==='pause')) G.mode=G.mode==='play'?'pause':'play';
  if(e.code==='KeyM') G.muted=!G.muted;
  if(e.code==='KeyL'&&G.mode==='play') saveGame();
  if(e.code==='Enter'&&G.mode==='title'){ ensureAudio(); startGame(); }
  if(e.code==='Enter'&&(G.mode==='dead'||G.mode==='win')) startGame();
});
addEventListener('keyup',e=>{ const k=KEYMAP[e.code]; if(k) G.keys[k]=false; });
cv.addEventListener('mousemove',e=>{ const r=cv.getBoundingClientRect(); G.mouse.x=(e.clientX-r.left)*(W/r.width); G.mouse.y=(e.clientY-r.top)*(H/r.height); });
cv.addEventListener('mousedown',e=>{ ensureAudio(); G.mouse.down=true; if(G.mode==='title') startGame(); else if(G.mode==='play') shoot(); });
addEventListener('mouseup',()=>{ G.mouse.down=false; });
cv.addEventListener('contextmenu',e=>e.preventDefault());

/* ---------- spawning ---------- */
const CAR_COLORS=['#c0392b','#2980b9','#f1c40f','#ecf0f1','#8e44ad','#e67e22','#16a085','#2c3e50','#d35400','#7f8c8d'];
function spawnCar(x,y,police){
  const c={x,y,a:rand(0,TAU),speed:0,police:!!police,col:police?'#1a1a2e':'#000',body:police?'#e8e8e8':CAR_COLORS[irand(0,CAR_COLORS.length-1)],w:46,h:24,driver:true,dead:false};
  G.cars.push(c); return c;
}
function spawnTraffic(n){
  for(let i=0;i<n;i++){
    const rx=ROADS_X[irand(0,ROADS_X.length-1)], ry=ROADS_Y[irand(0,ROADS_Y.length-1)];
    const horiz=Math.random()<0.5;
    spawnCar(horiz?rand(100,WORLD.w-100):rx, horiz?ry:rand(100,WORLD.h-100));
  }
}
function spawnPed(x,y){
  const p={x,y,a:rand(0,TAU),speed:rand(28,55),col:['#e74c3c','#3498db','#2ecc71','#f39c12','#9b59b6','#ecf0f1'][irand(0,5)],t:rand(0,5),panic:0};
  G.peds.push(p); return p;
}
function spawnPeds(n){ for(let i=0;i<n;i++) spawnPed(rand(150,WORLD.w-150),rand(150,WORLD.h-150)); }
function spawnCop(x,y){
  const c=spawnCar(x,y,true); c.speed=0; G.cops.push(c); return c;
}
function spawnPickups(){
  G.pickups=[
    {x:2450,y:300,kind:'crate',taken:false},{x:2900,y:560,kind:'crate',taken:false},{x:2450,y:620,kind:'crate',taken:false},
    {x:900,y:300,kind:'health',taken:false},{x:1800,y:1400,kind:'health',taken:false},{x:600,y:2200,kind:'cash',taken:false},
    {x:2600,y:1900,kind:'cash',taken:false},{x:1500,y:600,kind:'cash',taken:false},
  ];
}
function resetWorld(){
  G.cars=[]; G.peds=[]; G.cops=[]; G.bullets=[]; G.parts=[];
  spawnTraffic(16); spawnPeds(26); spawnPickups();
  G.player.x=1500; G.player.y=1150; G.player.a=-Math.PI/2; G.player.inCar=null; G.player.speed=0;
  G.cash=120; G.health=100; G.wanted=0; G.wantedHeat=0; G.kills=0; G.carsStolen=0;
  setMission(0);
}
function startGame(){
  resetWorld();
  G.mode='play'; G.time=0;
  flash('Welcome to Solmar Bay — find Marco\'s package at the Harbor.');
}

/* ---------- wanted / police ---------- */
function raiseWanted(n){
  G.wanted=clamp(G.wanted+n,0,5); G.wantedHeat=100;
  if(G.wanted>=1&&G.cops.length<G.wanted+1){
    for(let i=0;i<2;i++) spawnCop(G.player.x+rand(-500,500),G.player.y+rand(-500,500));
    sfx.siren();
  }
}
function updateWanted(dt){
  if(G.wanted>0){
    const seen = G.cops.some(c=>dist(c.x,c.y,G.player.x,G.player.y)<420);
    if(!seen){ G.wantedHeat-=dt*6; if(G.wantedHeat<=0){ G.wanted--; G.wantedHeat= G.wanted>0?60:0; flash(G.wanted>0?'Heat cooling off…':'You lost the cops. Clean.'); } }
    else G.wantedHeat=100;
  }
}

/* ---------- combat ---------- */
function shoot(){
  if(!AC) ensureAudio();
  const p=G.player;
  const sx=p.x, sy=p.y;
  const wx=G.cam.x+(G.mouse.x-W/2), wy=G.cam.y+(G.mouse.y-H/2);
  const a=Math.atan2(wy-sy,wx-sx);
  G.bullets.push({x:sx+Math.cos(a)*22,y:sy+Math.sin(a)*22,vx:Math.cos(a)*620,vy:Math.sin(a)*620,life:0.7,from:'player'});
  sfx.shoot();
  if(G.wanted<1) raiseWanted(1);
}
function updateBullets(dt){
  for(const b of G.bullets){
    b.x+=b.vx*dt; b.y+=b.vy*dt; b.life-=dt;
    if(hitBuilding(b.x,b.y,2)) b.life=0;
    // hit cops
    for(const c of G.cops){
      if(!c.dead&&dist(b.x,b.y,c.x,c.y)<26){ b.life=0; c.dead=true; G.kills++; addCash(25); burst(c.x,c.y,'#ffdd55'); raiseWanted(1); flash('Cop down. +$25'); break; }
    }
    // hit mission guards
    for(const g of G.guards||[]){
      if(!g.dead&&dist(b.x,b.y,g.x,g.y)<20){ b.life=0; g.hp-=34; if(g.hp<=0){ g.dead=true; G.kills++; addCash(50); burst(g.x,g.y,'#ff5555'); checkMission(); } break; }
    }
  }
  G.bullets=G.bullets.filter(b=>b.life>0);
}
function burst(x,y,col){ for(let i=0;i<14;i++) G.parts.push({x,y,vx:rand(-160,160),vy:rand(-160,160),life:rand(0.3,0.7),col}); }
</script>

<script>
"use strict";
/* ---------- player movement ---------- */
function tryMove(x,y,r){
  // axis-separated so the player slides along walls
  if(!solidAt(x,G.player.y,r)) G.player.x=x;
  if(!solidAt(G.player.x,y,r)) G.player.y=y;
}
function updatePlayer(dt){
  const p=G.player, k=G.keys;
  if(p.inCar){ updateDriving(dt); return; }
  const run=k.run?1.7:1;
  let mx=(k.right?1:0)-(k.left?1:0), my=(k.down?1:0)-(k.up?1:0);
  if(mx||my){
    const l=Math.hypot(mx,my); mx/=l; my/=l;
    const sp=190*run;
    tryMove(p.x+mx*sp*dt, p.y+my*sp*dt, 13);
    p.a=Math.atan2(my,mx); p.walk+=dt*10;
  } else p.walk=0;
  if(k.use){ k.use=false; tryEnterCar(); }
  // pickups
  for(const pk of G.pickups){
    if(!pk.taken&&dist(p.x,p.y,pk.x,pk.y)<30){
      pk.taken=true; sfx.pickup();
      if(pk.kind==='health'){ G.health=Math.min(100,G.health+40); flash('Health +40'); }
      else if(pk.kind==='cash'){ addCash(80); flash('Found $80 cash!'); }
      else if(pk.kind==='crate'){ G.missionStep++; flash('Crate '+G.missionStep+'/3 collected'); checkMission(); }
    }
  }
}
function nearestCar(maxD){
  let best=null,bd=maxD;
  for(const c of G.cars){ if(c.dead) continue; const d=dist(G.player.x,G.player.y,c.x,c.y); if(d<bd){bd=d;best=c;} }
  return best;
}
function tryEnterCar(){
  const c=nearestCar(70);
  if(!c) return;
  G.player.inCar=c; c.speed=0;
  if(!c.police&&c.driver){ c.driver=false; G.carsStolen++; raiseWanted(1); flash('Car stolen! The owner ran off. Wanted +1'); sfx.steal(); }
  else flash(c.police?'You jacked a cop car?!':'In the car — drive!');
}
function updateDriving(dt){
  const p=G.player, c=p.inCar, k=G.keys;
  if(!c){ p.inCar=null; return; }
  const accel=k.up?1:0, rev=k.down?1:0;
  const top=460;
  if(accel) c.speed+=420*dt;
  else if(rev) c.speed-=300*dt;
  else c.speed*=Math.pow(0.4,dt);
  if(k.brake) c.speed*=Math.pow(0.02,dt);
  c.speed=clamp(c.speed,-160,top);
  const steer=((k.left?1:0)-(k.right?1:0))*(c.speed>=0?1:-1);
  c.a+=steer*1.9*dt*Math.min(1,Math.abs(c.speed)/140);
  const nx=c.x+Math.cos(c.a)*c.speed*dt, ny=c.y+Math.sin(c.a)*c.speed*dt;
  if(solidAt(nx,ny,24)){ c.speed*=-0.35; sfx.crash(); G.shake=6; }
  else { c.x=nx; c.y=ny; }
  p.x=c.x; p.y=c.y; p.a=c.a;
  // run over peds (raises wanted) — classic, keep it rare & costly
  for(const pd of G.peds){
    if(dist(pd.x,pd.y,c.x,c.y)<26&&Math.abs(c.speed)>120){
      pd.x=-9999; burst(pd.x,pd.y,'#ff5555'); raiseWanted(1); flash('You hit a pedestrian! Wanted +1');
    }
  }
  if(k.use){ k.use=false; p.inCar=null; p.x=c.x+Math.cos(c.a+Math.PI/2)*34; p.y=c.y+Math.sin(c.a+Math.PI/2)*34; }
  if(engineGain) engineGain.gain.value=0.02+Math.abs(c.speed)/460*0.05;
  if(engineOsc) engineOsc.frequency.value=55+Math.abs(c.speed)*0.22;
}

/* ---------- traffic & pedestrians ---------- */
function updateTraffic(dt){
  for(const c of G.cars){
    if(c.dead) continue;
    if(c===G.player.inCar) continue;
    if(c.police) continue;
    // cruise along roads: pick nearest road axis and drive
    const onX=ROADS_X.reduce((a,b)=>Math.abs(c.x-b)<Math.abs(c.x-a)?b:a);
    const onY=ROADS_Y.reduce((a,b)=>Math.abs(c.y-b)<Math.abs(c.y-a)?b:a);
    const targetA = Math.abs(c.x-onX)<Math.abs(c.y-onY) ? (c.y<onY?Math.PI/2:-Math.PI/2) : (c.x<onX?0:Math.PI);
    c.a=angLerp(c.a,targetA,dt*1.2);
    c.speed=angLerp(c.speed,95,dt*0.8);
    const nx=c.x+Math.cos(c.a)*c.speed*dt, ny=c.y+Math.sin(c.a)*c.speed*dt;
    if(!solidAt(nx,ny,24)){ c.x=nx; c.y=ny; }
    else c.a+=Math.PI/2;
    // keep traffic on roads: respawn wanderers
    if(!onRoad(c.x,c.y)&&Math.random()<dt*0.05){ c.x=ROADS_X[irand(0,ROADS_X.length-1)]; c.y=ROADS_Y[irand(0,ROADS_Y.length-1)]; }
  }
  for(const pd of G.peds){
    if(pd.x<-100) continue;
    pd.t-=dt;
    if(pd.t<=0){ pd.a=rand(0,TAU); pd.t=rand(2,6); }
    if(pd.panic>0){ pd.panic-=dt; pd.speed=150; } else pd.speed=42;
    const nx=pd.x+Math.cos(pd.a)*pd.speed*dt, ny=pd.y+Math.sin(pd.a)*pd.speed*dt;
    if(!solidAt(nx,ny,10)&&!onRoad(nx,ny)||pd.panic>0){ pd.x=nx; pd.y=ny; }
    else pd.a+=Math.PI/2;
    if(dist(pd.x,pd.y,G.player.x,G.player.y)<90&&G.wanted>0) pd.panic=2;
  }
}

/* ---------- police AI ---------- */
function updateCops(dt){
  for(const c of G.cops){
    if(c.dead) continue;
    const p=G.player;
    const d=dist(c.x,c.y,p.x,p.y);
    if(G.wanted<=0){ // patrol away
      c.speed=angLerp(c.speed,80,dt); c.a=angLerp(c.a,Math.atan2(p.y-c.y,p.x-c.x)+Math.PI,dt*0.5);
    } else {
      const ta=Math.atan2(p.y-c.y,p.x-c.x);
      c.a=angLerp(c.a,ta,dt*2.2);
      c.speed=angLerp(c.speed,Math.min(500,330+G.wanted*35),dt*1.5);
      if(d<40){ // ram the player
        if(p.inCar){ p.inCar.speed*=0.55; G.shake=8; sfx.crash(); }
        else { G.health-=22*dt*3; sfx.hurt(); }
      }
      if(Math.random()<dt*0.25) sfx.siren();
    }
    const nx=c.x+Math.cos(c.a)*c.speed*dt, ny=c.y+Math.sin(c.a)*c.speed*dt;
    if(!solidAt(nx,ny,24)){ c.x=nx; c.y=ny; } else { c.speed*=0.5; c.a+=0.6; }
    // shooting at high wanted
    if(G.wanted>=3&&d<380&&Math.random()<dt*0.6){
      const a=Math.atan2(p.y-c.y,p.x-c.x)+rand(-0.12,0.12);
      G.bullets.push({x:c.x,y:c.y,vx:Math.cos(a)*520,vy:Math.sin(a)*520,life:0.8,from:'cop'});
    }
  }
  // cop bullets hurt the player
  for(const b of G.bullets){
    if(b.from==='cop'&&dist(b.x,b.y,G.player.x,G.player.y)<16){ b.life=0; G.health-=8; sfx.hurt(); G.shake=4; }
  }
  G.cops=G.cops.filter(c=>!c.dead||dist(c.x,c.y,G.player.x,G.player.y)<1200);
}

/* ---------- missions ---------- */
function checkMission(){
  const m=MISSIONS[G.mission];
  if(!m) return;
  if(m.kind==='goto'&&G.objective&&dist(G.player.x,G.player.y,G.objective.x,G.objective.y)<60) return completeMission();
  if(m.kind==='collect'&&G.missionStep>=m.need) return completeMission();
  if(m.kind==='escape'&&G.wanted===0&&G.objective&&dist(G.player.x,G.player.y,G.objective.x,G.objective.y)<80) return completeMission();
  if(m.kind==='fight'&&(G.guards||[]).filter(g=>!g.dead).length===0&&(G.guards||[]).length>=m.need) return completeMission();
}
function completeMission(){
  const m=MISSIONS[G.mission];
  addCash(300+G.mission*200); sfx.mission();
  flash(m.done+' +$'+(300+G.mission*200));
  if(G.mission>=MISSIONS.length-1){ G.mode='win'; return; }
  const next=G.mission+1;
  if(next===3){ // casino guards spawn
    G.guards=[];
    for(let i=0;i<4;i++) G.guards.push({x:430+rand(-90,90),y:1135+rand(-60,60),hp:100,dead:false,a:0,t:rand(0,2)});
  }
  setMission(next);
}
function updateGuards(dt){
  for(const g of G.guards||[]){
    if(g.dead) continue;
    g.t-=dt;
    const d=dist(g.x,g.y,G.player.x,G.player.y);
    if(d<420){
      g.a=Math.atan2(G.player.y-g.y,G.player.x-g.x);
      if(g.t<=0){ g.t=rand(0.9,1.6);
        G.bullets.push({x:g.x,y:g.y,vx:Math.cos(g.a)*480,vy:Math.sin(g.a)*480,life:0.8,from:'cop'}); }
      if(d>180){ g.x+=Math.cos(g.a)*70*dt; g.y+=Math.sin(g.a)*70*dt; }
    }
  }
}

/* ---------- save / load ---------- */
function saveGame(){
  try{
    localStorage.setItem(SAVE_KEY,JSON.stringify({x:G.player.x,y:G.player.y,cash:G.cash,health:G.health,mission:G.mission,step:G.missionStep,kills:G.kills,stolen:G.carsStolen,score:G.score}));
    G.saveFlash=2; flash('Game saved.'); sfx.pickup();
  }catch(e){ flash('Save failed (storage blocked).'); }
}
function loadSave(){
  try{ const s=JSON.parse(localStorage.getItem(SAVE_KEY)||'null'); return s; }catch(e){ return null; }
}
</script>

